def solve(inputs: dict) -> float:
 m=int(inputs.get('MODE',1))
 if m==1:
  x=int(inputs['X']);a=int(inputs['A']);b=int(inputs['B']);c=int(inputs['C']);k=int(inputs['K']);mask=2**32-1
  for _ in range(k):x^=(x<<a)&mask;x&=mask;x^=x>>b;x&=mask;x^=(x<<c)&mask;x&=mask
  return float(x)
 if m==2:
  s=int(inputs['SEED']);a=int(inputs['A']);b=int(inputs['B']);q=int(inputs['M']);k=int(inputs['K'])
  for _ in range(k):s=(a*s+b)%q
  return float(s)
 if m==3:
  j=0
  for i in range(1,int(inputs['N'])+1):j=(j+int(inputs['K']))%i
  return float(j+1)
 if m==4:
  q=int(inputs['MOD']);k=int(inputs['K']);z=(int(inputs['A']),int(inputs['B']),int(inputs['C']),int(inputs['D']));r=(1,0,0,1)
  def f(x,y):return tuple(((x[i//2*2]*y[i%2]+x[i//2*2+1]*y[i%2+2])%q) for i in range(4))
  while k:
   if k&1:r=f(r,z)
   z=f(z,z);k//=2
  return float(sum(r))
 if m==5:return float(pow(int(inputs['BASE']),int(inputs['EXP']),int(inputs['MOD'])))
 if m==6:
  n=int(inputs['COUNT']);x=0;p=1
  for i in range(1,n+1):
   r=int(inputs['R'+str(i)]);q=int(inputs['M'+str(i)]);t=(r-x)*pow(p,-1,q)%q;x+=p*t;p*=q
  return float(x%p)
 if m==7:
  x=int(inputs['X']);c=int(inputs['C']);q=int(inputs['MOD'])
  for _ in range(int(inputs['K'])):x=(x*x+c)%q
  return float(x)
 return 0.0

